function App() {
  const [pathname, setPathname] = useState('/');
  const links = [['/', 'Home'], ['/docs', 'Docs'], ['/pricing', 'Pricing']];
  function isActive(href) {
    return pathname === href;
  }
  return (
    <nav style={{ fontFamily: 'system-ui', padding: 16, display: 'flex', gap: 12 }}>
      {links.map(([href, label]) => (
        <a key={href} href={href}
          onClick={(e) => { e.preventDefault(); setPathname(href); }}
          aria-current={isActive(href) ? 'page' : undefined}
          style={{ fontWeight: isActive(href) ? 700 : 400, textDecoration: 'none' }}>
          {label}
        </a>
      ))}
    </nav>
  );
}
